/* Melhorias em homologação: nenhum registro é apagado automaticamente. */
(()=>{
 if(window.__hsjFluxo20261023)return;window.__hsjFluxo20261023=true;
 const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','"':'&quot;'}[c]));
 const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toUpperCase().replace(/\s+/g,' ');
 const duplicates=()=>{const m=new Map();for(const x of S.rows){const cpf=String(x.cpf||'').replace(/\D/g,'');const n=norm(x.patient_name);const k=cpf.length===11?'CPF:'+cpf:n?'NOME:'+n:'';if(!k)continue;if(!m.has(k))m.set(k,[]);m.get(k).push(x);}return [...m.values()].filter(a=>a.length>1)};
 function exportExcel(){const view=S.view;const rows=view==='indicadores'?filtered(S.rows):view==='suspensas'?suspendRows():view==='duploj'?filtered(S.rows.filter(x=>x.double_j===true||x.double_j==='SIM')):stageRows(view);
 const fields=['patient_name','cpf','ids','procedure_name','specialty','surgeon','patient_status','stage','aih_request_date','authorization_date','programming_date','surgery_date','phone'];
 const labels=['Paciente','CPF','IDS','Procedimento','Especialidade','Médico','Situação','Etapa','Data AIH','Autorização','Programação','Cirurgia','Telefone'];
 const xml=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
 const row=arr=>'<Row>'+arr.map(v=>'<Cell><Data ss:Type="String">'+xml(v)+'</Data></Cell>').join('')+'</Row>';
 const body='<?xml version="1.0" encoding="UTF-8"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Pacientes"><Table>'+row(labels)+rows.map(x=>row(fields.map(k=>x[k]??''))).join('')+'</Table></Worksheet></Workbook>';
 const a=document.createElement('a'),url=URL.createObjectURL(new Blob([body],{type:'application/vnd.ms-excel;charset=utf-8'}));a.href=url;a.download='HSJ_'+view+'_'+new Date().toISOString().slice(0,10)+'.xls';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);
 }
 window.hsjExportExcel=exportExcel;
 window.hsjShowDuplicates=function(){const groups=duplicates();const html=groups.map(g=>'<div style="padding:9px;border-bottom:1px solid #ddd">'+g.map(x=>'<div><b>'+safe(x.patient_name)+'</b> — CPF '+safe(x.cpf||'não informado')+' — IDS '+safe(x.ids||'—')+' — '+safe(x.stage||'')+' <button class="btn small red" onclick="hsjDeactivateDuplicate(\''+x.id+'\')">Excluir</button></div>').join('')+'</div>').join('');document.getElementById('modal').innerHTML='<div class="back"><div class="modal"><div class="mh"><b>Possíveis cadastros duplicados ('+groups.length+' grupos)</b><button class="btn" onclick="document.getElementById(\'modal\').innerHTML=\'\'">Fechar</button></div><div class="mb"><div class="notice">Confira os identificadores: homônimos podem representar pessoas diferentes. Excluir aqui significa desativar o cadastro, preservando o registro para auditoria.</div>'+(html||'Nenhum possível duplicado encontrado.')+'</div></div></div>'};
 window.hsjDeactivateDuplicate=async function(id){const x=S.rows.find(r=>r.id===id);if(!x)return;if(!confirm('Confirma DESATIVAR o cadastro de '+x.patient_name+'? Verifique se o cadastro correto será mantido. O histórico não será apagado.'))return;
 try{const r=await api('/rest/v1/surgeries?id=eq.'+encodeURIComponent(id)+'&active=eq.true',{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({active:false,updated_by:uid})});if(!Array.isArray(r)||r.length!==1)throw Error('Cadastro não atualizado.');await load();document.getElementById('modal').innerHTML='';renderCurrent()}catch(e){alert('Não foi possível desativar: '+e.message)}};
 // Uma etapa principal por paciente. Consultas antigas permanecem no histórico, mas não na fila operacional.
 window.consultRows=function(){return S.rows.filter(x=>x.stage==='consulta_preop')};
 // Impedir movimentação silenciosa sobre atualização feita por outro computador.
 window.nextStage=async function(id){const x=S.rows.find(r=>r.id===id);if(!x)return alert('Registro não localizado.');const i=stageOrder.indexOf(x.stage);if(i<0||i===stageOrder.length-1)return alert('Não há próxima etapa configurada.');const to=stageOrder[i+1];if(!confirm('Mover '+x.patient_name+' exclusivamente de '+(labels[x.stage]||x.stage)+' para '+(labels[to]||to)+'?'))return;
 try{let q='/rest/v1/surgeries?id=eq.'+encodeURIComponent(id)+'&stage=eq.'+encodeURIComponent(x.stage);if(x.updated_at)q+='&updated_at=eq.'+encodeURIComponent(x.updated_at);const r=await api(q,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({stage:to,updated_by:uid})});if(!Array.isArray(r)||r.length!==1)throw Error('Movimentação não efetivada: o cadastro foi alterado por outro operador.');await load();renderCurrent()}catch(e){alert(e.message);await load();renderCurrent()}};
 // Controles visíveis em todas as abas, sem modificar os dados carregados.
 function decorate(){const content=document.getElementById('content');if(!content||!content.firstElementChild)return;const header=content.querySelector('.section-head');if(!header||content.querySelector('#hsjTools'))return;const tools=document.createElement('div');tools.id='hsjTools';tools.style.cssText='display:flex;gap:6px;flex-wrap:wrap;margin:8px 0';const b=document.createElement('button');b.className='btn';b.textContent='⬇ Excel desta aba';b.onclick=exportExcel;const p=document.createElement('button');p.className='btn';p.textContent='🖨 Imprimir esta aba';p.onclick=()=>window.print();const d=document.createElement('button');d.className='btn orange';d.textContent='⚠ Verificar duplicados ('+duplicates().length+')';d.onclick=window.hsjShowDuplicates;tools.append(b,p,d);header.appendChild(tools)}
 const root=document.getElementById('content');if(root){const obs=new MutationObserver(()=>{if(!root.querySelector('#hsjTools'))decorate()});obs.observe(root,{childList:true});decorate()}
 const style=document.createElement('style');style.textContent='@media print {.topbar,.filterbar,.tabs,.acts,#hsjTools,.mf{display:none!important}.wrap{max-width:none;padding:0}.card{box-shadow:none;border:0}.table{min-width:0;font-size:10px}}';document.head.appendChild(style);
})();